      "id": "luxury-mens-fashion-ai-portrait-prompts",
      "title": "5 AI Portrait Prompts for Men: Luxury Fashion",
      "slug": "luxury-mens-fashion-ai-portrait-prompts",
      "category": "AI Prompts",
      "excerpt": "Use five AI portrait prompts for men and learn how to control menswear, pose, setting, identity guidance, and common fashion-image problems.",
      "publishDate": "2026-06-01",
      "date": "2026-06-01",
      "readingTime": 12,
      "coverImage": "/uploads/luxury-mens-fashion-ai-portrait-prompts.webp",
